window.MONSTER_CHUNK_133 = [{"name":"Glacial Ooze","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"ooze","subtypes":["cold"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size, +0 natural","hp":69,"hd":"6d8+42","hdvalue":6,"fort":9,"ref":-3,"will":-3,"dr":"5/bludgeoning","immunities":["cold","ooze traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":20}],"melee":"slam +5 (2d4+3 plus 1d6 cold)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"cold"},{"type":"engulf","details":"DC 15, 1d6 cold and freezing embrace"},{"type":"freeze"}],"strength":15,"dexterity":1,"constitution":24,"wisdom":1,"charisma":1,"baseatk":4,"cmb":7,"cmd":12,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":10}],"environments":["cold plains"],"organizations":["solitary"],"treasure":"none","description_visual":"At first glance what appears to be a snow bank or mound of snow reveals itself to be a sentient creature formed of snow and ice.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Cold","kind":"Ex","details":"A glacial ooze's form is extremely cold, dealing 1d6 cold damage with its slam attack. Creatures attacking a glacial ooze unarmed or with natural weapons take this cold damage each time one of their attacks hits."},{"type":"Freezing Embrace","kind":"Ex","details":"As a free action, a glacial ooze can encase an engulfed opponent in ice. A frozen creature takes 2d4 points of cold damage each round. A frozen creature can break free of the ice by making a successful DC 19 Strength check. The ice is AC 10, hardness 0, and has 10 hit points per 5-foot section. A frozen creature cannot use a weapon to break free even if it was holding it when it was frozen. Spells with verbal, material, or somatic components cannot be cast by a creature encased in ice. The check DC is Strength-based and includes a +4 racial bonus."},{"type":"Transparent","kind":"Ex","details":"A glacial ooze is hard to identify, even under ideal conditions, and it takes a DC 20 Perception check to notice one. Creatures who fail to notice a glacial ooze and walk into it are automatically engulfed."}],"description":"This creature appears as translucent bluish-white icy sludge about 10 ft. on each side (though larger specimens have been encountered). This ooze is conjectured to be a relative of the gelatinous cube, though a link between the two has yet to be established.\n\nThe glacial ooze is at home in or out of the water, and is often encountered inhabiting frozen or partially frozen lakes and rivers. It gains nutrients from water and snow, absorbing them into its gelatinous form and digesting them. Like many oozes, the glacial ooze is a scavenger and feeds on the carcasses of once living creatures that have frozen to death.\n\nRather than completely digesting such creatures, the glacial ooze absorbs all bodily fluids and liquids from a corpse, leaving behind a frozen and rotted husk.\n\nA glacial ooze attacks by forming a pseudopod and pummeling a foe. Against creatures smaller than itself, it simply moves across them, absorbing them into its form and holding them until they freeze to death.","ecology":"","habitat_society":""},{"name":"Gray-Scale Inphidian","cr":6,"xp":2400,"alignment":"NE","size":"Large","type":"monstrous humanoid","subtypes":["reptilian"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":8,"ac_flat_footed":17,"ac_mods":"-1 Dex, +9 natural, -1 size","hp":76,"hd":"8d10+32","hdvalue":8,"fort":6,"ref":5,"will":7,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"swim","speed":20}],"melee":"2 snake-hands +13 (1d8+6 plus poison and grab), bite +13 (2d6+6/19-20 plus poison)","space":"10 ft.","reach":"10 ft.","strength":22,"dexterity":8,"constitution":18,"intelligence":6,"wisdom":12,"charisma":12,"baseatk":8,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":24,"feats":[{"feat":"Cleave"},{"feat":"Improved Critical (bite)"},{"feat":"Power Attack"},{"feat":"Uncontrolled Rage"}],"skills":[{"skill":"Climb","value":14},{"skill":"Intimidate","value":8},{"skill":"Perception","value":12},{"skill":"Stealth","value":2},{"skill":"Swim","value":14}],"languages":["Inphidian"],"sq":[{"type":"magic bane","details":"see text"}],"environments":["any underground","warm forests","warm plains"],"organizations":["solitary","gang (1 gray-scale inphidian plus 2-3 cobra-back inphidians)"],"treasure":"incidental","description_visual":"This hulking brute is covered in slate gray scales. It has the head of a giant venomous snake, and its long, muscular arms end in large snake heads where its hands should be.","group":"Inphidian","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Magic Bane","kind":"Ex","details":"There is a 50% chance that any gray-scale encountered has this ability. It grants the gray-scale a +2 bonus on attack and damage rolls against spellcasters. A gray-scale with this special ability also takes a -2 penalty on all saves against spells and spell-like abilities."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 20 Fort; frequency 1/ round for 6 rounds; effect 1d4 Str and 1d4 Con; cure 2 consecutive saves. The save DC is Constitution-based and includes a +2 racial bonus. Uncontrolled Rage Uncontrolled Rage is a new feat detailed in the appendix."}],"description":"The gray-scale inphidian (also called the abomination inphidian) is the result of a magical experiment gone awry. Foul, dark magic brought down by inphidian sorcerers on others of their race resulted in this creature; the strongest of the inphidian race perhaps, but also the most weak-minded and slowest. Most gray-scales seemingly have no memories of their past life or the tortures inflicted on them; those that do however, have both a hatred and fear for magic and those that wield it.\n\nGray-scales are considered by many inphidian nests to be dangerous, unstable, and an abomination against the race, particularly the gray-scales with the magic bane quality. These feelings, often times come from inphidian night adders (some of whom likely assisted in helping the gray-scale into its current state). Most often, gray-scales are shunned by their inphidian nest and cast out, left to wander the world and survive on their own, by whatever means they can. In some instances, a gray-scale stays with its nest, never fully accepted by many of the other inphidians, but tolerated, feared and respected for their battle skills. In these cases, one or more gray-scales serve as guards for the nest, or the muscle for an inphidian raiding party.\n\nA gray-scale inphidian appears as an 8-foot tall hulking and slightly hunched humanoid with slate gray scales, the head of a giant viper with elongated fangs and red eyes, and the distinguishing inphidian characteristic: the heads of vipers in place of its hands. They shun wearing both armor and clothing. Gray-scales understand the Inphidian language, but seemingly have trouble speaking it; communicating in a slow and broken tone.\n\nPerhaps a side-effect of the experiments conducted on them, or perhaps by design, but no sightings of female gray-scales have ever been reported. Likewise, gray-scales appear to be sterile, unable to reproduce with others of the inphidian race.\n\nIn battle, a gray-scale inphidian prefers to overwhelm its opponents with its pure strength instead of attacking from ambush. It lashes out with both snake hands followed closely with a vicious bite from its viper head. A grabbed opponent is repeatedly bitten by the gray-scale until either it is dead or wounded enough to be out of the fight. The gray-scale then turns its attention to another opponent. If faced with a spellcasting opponent, it usually focuses all attention in the spellcaster's direction, even pushing through other opponents to get to the spellcaster.","ecology":"","habitat_society":""},{"name":"Grig Swarm","cr":6,"xp":2400,"alignment":"NG","size":"Tiny","type":"fey","subtypes":["swarm"],"init":4,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +2 natural, +2 size","hp":45,"hd":"10d6+10","hdvalue":10,"fort":6,"ref":11,"will":8,"dr":"5/cold iron","immunities":["swarm traits"],"sr":17,"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"swarm (2d6)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 16"},{"type":"fiddle"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"disguise self"},{"spell":"entangle"},{"spell":"invisibility","details":"self only"},{"spell":"pyrotechnics"},{"spell":"ventriloquism"}]}],"strength":5,"dexterity":18,"constitution":13,"intelligence":10,"wisdom":13,"charisma":14,"baseatk":5,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":17,"special":"+23 jumping"},{"skill":"Craft (any)","value":13},{"skill":"Escape Artist","value":17},{"skill":"Fly","value":4},{"skill":"Perception","value":14},{"skill":"Perform (string instruments)","value":15},{"skill":"Stealth","value":25,"special":"+29 in forests"}],"languages":["Common","Sylvan"],"environments":["temperate forests"],"organizations":["solitary","tangle (2-4 swarms)","cyclone (5-10 swarms)"],"treasure":"none","description_visual":"Winged man-shaped creatures with blue skin and cricket legs buzz about in a dense mass both hypnotic and frightening.","group":"Grig","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fiddle","kind":"Su","details":"The grigs that make up a grig swarm carry tiny, grig-sized fiddles. When the fiddlers play, any non-sprite within 30 ft. of the instruments must make a successful DC 17 Will save or be affected as though by irresistible dance for as long as the playing continues. The save DC is Charisma-based."}],"description":"A grig swarm is a large mass of flying grigs. Normally grigs don't gather into groups larger than 80 or so creatures. But sometimes when several tribes come together, they join as a grig swarm.\n\nThe individual grigs that make up the swarm have light blue skin, forest-green hair, and brown hairy legs, and usually wear tunics or brightly colored vests with buttons made from tiny gems. A grig stands 1-1/2 ft. tall and weighs about 1 pound.\n\nA grig swarm normally attacks by surrounding and enveloping its opponents. Before closing to melee range, a swarm uses its entangle ability to bind its foes. If facing destruction, a swarm often turns invisible and flees.","ecology":"","habitat_society":""},{"name":"Guardian Cimota","cr":6,"xp":2400,"alignment":"LE","size":"Medium","type":"undead","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense"}],"auras":["unnatural aura (30 ft.)"],"ac":20,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+6 natural, +4 Dex","hp":85,"hd":"8d8+48","hdvalue":8,"fort":8,"ref":7,"will":8,"defensive_abilities":["channel resistance +4","displacement","unholy existence"],"immunities":["cold","electricity","undead traits"],"sr":15,"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 scimitars +11 (1d6+4 plus 1d6 negative energy/18-20, evil-aligned)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"manifestation"},{"type":"superior two-weapon fighting"}],"strength":18,"dexterity":16,"intelligence":14,"wisdom":14,"charisma":22,"baseatk":6,"cmb":10,"cmd":20,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Diplomacy","value":13},{"skill":"Fly","value":12},{"skill":"Intimidate","value":17},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":13}],"languages":["Common","Infernal"],"environments":["any"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"A figure materializes out of the surrounding shadows. It has the black cloak and cowl of a monk, floating in the air with no visible body. Menacing green eyes glare from inside the dark hood.","group":"Cimota","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Displacement","kind":"Su","details":"Cimota manifest on the Prime Material Plane as a shifting cloud of shadows that coalesce into their cloaked and hooded forms. On any round that a cimota first manifests, its shifting forms affect it as a displacement spell. Attacks on a cimota at this time have a 50% miss chance as if the cimota had total concealment. Unlike actual total concealment, this displacement doesn't prevent enemies from targeting a cimota normally. This effect is canceled one round after a cimota manifests, or if a cimota takes any action in its new locale."},{"type":"Lifesense","kind":"Su","details":"A cimota notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Manifestation","kind":"Su","details":"As a standard action, a cimota can transport itself via planar travel from any point on the Prime Material Plane to another point within its defined area, or within 300 ft. of the artifact to which it is bound. A cimota may also lurk on the Negative Material Plane, prepared to manifest on the Prime Material if certain conditions are met, such as trespassers entering the area they are doomed to guard. A cimota cannot attack or move in the same round in which it manifests, although it may manifest as partial surprise action before initiative. A cimota benefits from displacement on the round in which it first manifests."},{"type":"Superior Two-Weapon Fighting","kind":"Ex","details":"A black skeleton usually fights with a short sword in each hand. Because of its magical nature, its Two-Weapon Fighting feat allows it to attack with both weapons at no penalty."},{"type":"Unholy Existence","kind":"Su","details":"Although it is possible to temporarily destroy a cimota's physical form, it will return in 1d6 days, manifesting again to continue its unholy existence. The only way to permanently destroy a cimota is to disrupt its existence by consecrating the ground to which it is tied or the destruction of the artifact to which it is bound. Sometimes, significant alteration of an unholy place, such as demolition of an evil temple or burning a haunted forest, could cause cimota to fade away permanently. Although their physical forms may be damaged by normal attacks, their unholy existence grants them spell resistance 17. Because cimota exist partially on the Negative Material Plane they are subject to banishment or other spells that affect outsiders."},{"type":"Unnatural Aura","kind":"Su","details":"Animals don't willingly approach within 30 ft. of a cimota unless a master makes a DC 25 Handle Animal, Ride, or wild empathy check. This aura takes effect when a cimota manifests on the Prime Material Plane. Animals that come within 30 ft. of a place where cimota are lurking on the Negative Material Plane, or an artifact to which a cimota is bound; Will be uneasy and show signs of disquiet."}],"description":"Cimota are the physical manifestations of evil thoughts and actions. They exist on the Negative Material Plane, manifesting in the Prime Material as cloaked figures. Their existence is always tied to a specific area or artifact that is imbued with ancient and highly malevolent evil. A cimota is able to manifest itself anywhere within an accursed locale that has given it life, or within 300 ft. of an evil artifact to which it is attached.\n\nThe physical form of a cimota is a floating figure in a monk's cassock. Green eyes glow deep within their raised cowls, but their bodies are entirely invisible. See invisibility, true sight, or some similar ability to see invisible objects will reveal a ghostly, black human figure within the cimota's cloak. Cimota are manifestations of evil that may be touched like any other creature. They take damage from normal weapons. Their unnatural existence allows them to fly on the Prime Material Plane just like an incorporeal creature, except that they cannot pass through solid objects. When a cimota is destroyed in combat only a few shreds of tattered black cloth remain to show that they ever existed.\n\nCimota are bound to repeat the evil thoughts and actions that created them. When they manifest they will endlessly repeat the deeds that spawned them. So, for instance, a group of cimota may haunt a ruined temple, re-enacting evil rituals. Cimota may guard an unholy site such as a city, forest or building. They will fight to the death to defend these places. Cimota who are bound to an artifact may act out the intentions of that artifact. A cimota might follow the owner of an artifact, for instance, slaying the owner's friends and associates while keeping its existence a secret. Within the parameters of their creation, cimota are capable of strategy, deception and intelligent tactics.\n\nCimota are created by evil energy. Their supernatural nature gives them the ability to fight with two fists or two weapons without penalty, each attack landing with the force and accuracy of a single weapon attack. Cimota attacks are either a rake of invisible claws or a blow from a fist. They are capable of delivering slashing or bludgeoning blows as needed.\n\nCimota are capable of speaking Common and Infernal. Their voices are either hollow, ringing and unnatural, or malevolent whispers. Most often cimota use their voices to chant or to shout out dire condemnations at intruders. They don't parley and they never negotiate unless it is to deceive mortals to their deaths.","ecology":"","habitat_society":"","credit":"Original author Mark R. Shipley  Originally appearing in The Black Monastery (© Frog God Games/ Mark R. Shipley, 2011)"},{"name":"Guardian Daemon","cr":6,"xp":2400,"alignment":"NE","size":"Large","type":"outsider","subtypes":["extraplanar"],"init":1,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":21,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+1 Dex, +11 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":5,"ref":7,"will":8,"dr":"10/cold iron or silver","immunities":["acid","hold","mind-affecting effects","poison","polymorph","sleep"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"weaknesses":["limited domain"],"speed":[{"type":"land","speed":30}],"melee":"bite +11 (2d6+4), 2 claws +11 (1d6+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"30 ft. cone, DC 17, 5d6 fire, useable every 1d4 rounds"}],"strength":18,"dexterity":12,"constitution":16,"intelligence":12,"wisdom":14,"charisma":14,"baseatk":8,"cmb":13,"cmd":24,"feats":[{"feat":"Blind-Fight"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":9},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":8},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":4},{"skill":"Survival","value":9}],"languages":["Abyssal","Common","Daemonic","Infernal","telepathy 100 ft."],"environments":["any"],"organizations":["solitary"],"treasure":"none (see text)","description_visual":"This entity resembles a large bipedal bear-like creature with upward curving horns, elongated fangs, and blackish-gray fur. Its hands end in eagle-like talons.","group":"Daemon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Limited Domain","kind":"Ex","details":"The realm of a guardian daemon encompasses only the area it is summoned to guard; a room, chamber, or treasure. The area can be no larger than 100 ft. + 10 ft. per caster level of the one who summoned it. The guardian daemon can wander freely in its area, but cannot move beyond the precincts of the designated area."}],"description":"Summoning a Guardian Daemon A guardian daemon can be summoned by a planar ally, greater planar ally, planar binding, greater planar binding or similar magic that allows a spellcaster to bring an outsider to the Material Plane.\n\nA guardian daemon is summoned to the Material Plane by a spellcaster with the task of guarding an area or treasure. These daemons vary in size and appearance, though most resemble large bears, wild cats, or apes with added daemonic characteristics (horns, elongated fangs and nails, and so on). Despite its varying appearance and form, the guardian daemon is a dangerous adversary. A typical guardian daemon stands 9 ft. tall and weighs about 800 pounds. Most guardian daemons are of neutral slant, though many, due to their daemonic heritage, are evil and usually only serve those of like alignment. A guardian daemon only initiates combat if the area it is guarding is entered or the treasure it is watching over is disturbed. Though guardian daemons can move both upright and on all fours, it always fights in a bipedal stance. When engaged in combat, it may move freely, but never leaves the area it is guarding (see limited domain above). A guardian daemon attacks using its breath weapon, bite, and claws. It defends the area it is tied to until either it or its opponents are dead.","ecology":"","habitat_society":"","credit":"The Guardian Daemon originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Hell Moth","cr":6,"xp":2400,"alignment":"NE","size":"Large","type":"aberration","subtypes":["extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":19,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+3 Dex, +7 natural, -1 size","hp":76,"hd":"9d8+36","hdvalue":9,"fort":6,"ref":6,"will":7,"resists":[{"type":"fire","value":20}],"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"bite +10 (1d6+7 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf"},{"type":"immolation"}],"strength":21,"dexterity":16,"constitution":17,"intelligence":6,"wisdom":12,"charisma":10,"baseatk":6,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":25,"feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":13},{"skill":"Stealth","value":8}],"environments":["any"],"organizations":["solitary","flock (3-6)"],"treasure":"none","description_visual":"This creature looks like a giant gray moth with spiraling bands of red and black on its body. It has large, thin, reddish-hued wings.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Engulf","kind":"Ex","details":"If a hell moth grapples an opponent it can wrap a Medium or smaller creature in its wings and body and automatically deal bite damage in each round it maintains the grapple. Attacks that hit an engulfing hell moth deal half their damage to the monster and half to the trapped victim."},{"type":"Immolation","kind":"Su","details":"A hell moth that has engulfed an opponent can detonate its body in a blast of hellish fire that deals 6d10 points of fire damage to itself and the engulfed opponent (no save). (Reduce the damage dealt to the hell moth by its fire resistance.) A hell moth can immolate itself once every 3 hours (providing it survives the immolation). Creatures within 10 ft. of the hell moth when it uses this ability must succeed on a DC 17 Reflex save or take 1d8 points of fire damage as clothes and combustibles ignite. The damage continues for another 1d4+4 rounds after the hell moth uses this ability or until the fire is extinguished. The save DC is Constitution-based."}],"description":"The hell moth is thought to have come from another plane, though sages are not quite sure of its exact origin. The hell moth attacks living creatures that wander too close to its lair. It otherwise resembles a large moth with an 8-foot wingspan.\n\nHell moths wait for their prey to pass nearby before attacking. If facing multiple opponents, they attempt to bite and usually don't employ their engulfing ability. Multiple hell moths work in concert with one another against opponents. When a hell moth has successfully engulfed a foe, it sets its own body on fire in a display of self-immolation that consumes both it and its engulfed opponent.","ecology":"","habitat_society":""},{"name":"Huge Salt Elemental","cr":6,"xp":2400,"alignment":"N","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["dehydration (20 ft., DC 17, 2d6)"],"ac":18,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+1 dodge, +9 natural, -2 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":2,"will":6,"dr":"5/-","immunities":["elemental traits"],"weaknesses":["vulnerability to water"],"speed":[{"type":"land","speed":20}],"melee":"2 claws +11 (2d6+5 plus salt poisoning)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"salt poisoning","details":"11 rounds, DC 17"}],"strength":21,"dexterity":10,"constitution":17,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":15,"cmd":26,"feats":[{"feat":"Cleave"},{"feat":"Dodge","type":"bonus"},{"feat":"Endurance"},{"feat":"Great Cleave"},{"feat":"Mobility"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":16},{"skill":"Knowledge (dungeoneering)","value":5},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":11},{"skill":"Stealth","value":3}],"languages":["Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This crystalline humanoid is slightly translucent and light gray in color. Its head has no discernible features and its power arms end in massive fists.","group":"Elemental","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Dehydration Aura","kind":"Su","details":"A salt elemental's aura draws moisture from an area centered on itself. Living creatures within range take damage (damage is detailed with each elemental) each round they remain in the area. A successful Fortitude save reduces the damage by half. This effect is especially devastating to plants, animals, and aquatic creatures, which take a -4 penalty on their saving throws. The save DC is Constitution-based."},{"type":"Earth Mastery","kind":"Ex","details":"A salt elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"},{"type":"Salt Poisoning","kind":"Ex","details":"Anyone hit by a salt elemental's claw attack is sickened for 3 rounds + 1 round per Hit Dice of the salt elemental. A successful Fortitude save negates this effect. The save DC is Constitution-based."},{"type":"Vulnerability to Water","kind":"Ex","details":"A salt elemental submerged in water that covers at least half its body takes 1d6 points of damage each round until it escapes. Damage from water-based attacks (such as the slam attack of a water elemental) deal +50% damage to a salt elemental."}],"description":"Salt elementals inhabit regions rich in salt upon the Plane of Earth. Some believe they originated on a pocket plane somewhere near the energy planes and Plane of Water; perhaps an Elemental Plane of Salt. Salt elementals, avoid large expanses of water at all costs, knowing exposure to such a large quantity spells disaster.\n\nSalt elementals spend most of their time wandering their realm and often make forays into other planes (except the Plane of Water), seeking creatures on which to feed. They are particularly fond of plants, which are extremely vulnerable to their dehydrating ability.\n\nA salt elemental generally appears as a humanoid with no discernible features, though they can take other forms, and some do, preferring to appear in the shape of large animals or giant vermin (usually beetles).","ecology":"","habitat_society":""},{"name":"Lantern Goat","cr":6,"xp":2400,"alignment":"CE","size":"Medium","type":"undead","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense","modifier":"60 ft."}],"ac":19,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +4 natural","hp":68,"hd":"8d8+32","hdvalue":8,"fort":5,"ref":6,"will":6,"immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"head butt +10 (1d6+1), 2 hooves +10 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"fear light"},{"type":"soul capture"}],"strength":13,"dexterity":18,"intelligence":6,"wisdom":10,"charisma":17,"baseatk":6,"cmb":7,"cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Perception","value":11},{"skill":"Stealth","value":9}],"environments":["any mountains"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a goat with tangled and patchy gray-and-white hair, and horns and hooves that appear to be made of stone. Its eyes are stark white. Around its neck hangs a dented and ugly iron lantern, glowing with a foul amber light.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fear Light","kind":"Su","details":"A lantern goat can emit an ugly yellow light from the lantern around its neck as a free action. All creatures within 60 ft. that view this light must succeed on a DC 17 Will save or be panicked for 1d4+4 rounds. A creature that succeeds on its save is immune to the fear light of that lantern goat for one day. The save DC is Charisma-based."},{"type":"Lifesense","kind":"Su","details":"A lantern goat notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability. It also senses the strength of their life force automatically, as if it had cast deathwatch."},{"type":"Soul Capture","kind":"Su","details":"Any living creature reduced to below 0 hit points while within 60 ft. of a lantern goat must succeed on a DC 17 Will save or have its soul drawn into the lantern goat's lantern. The DC increases by +1 for every hit point the character is below 0 (e.g., a character at -3 hit points must save at DC 20). Once captured, the lantern goat slowly digests the creature's soul over a period of 1 hour, using it to fuel its dark energies. A creature slain in this manner can only be returned to life by a resurrection, true resurrection, wish, or miracle. Raise dead has no effect on such a slain creature. If the lantern goat is slain and the lantern destroyed, the soul is released back to the body if still living. The lantern cannot be destroyed or removed until the lantern goat is destroyed. The save DC is Charisma-based."}],"description":"Lantern goats are undead wanderers thought to be the coalescence of souls of people who died while lost in the wilderness. Just as normal goats sometimes drift from the shepherd's care and fall prey to the dangers of the wild, so too do humans and demihumans often meet with a dire end while trekking alone in the hills. Whether they die of exposure or become a predator's meal, these lost travelers usually journey in spirit form to the afterlife. Some, however, if they perish too close to a lantern goat, find their souls drawn into the fell receptacle the creature wears around its neck.\n\nThe scarred and battered lantern that depends from the goat's neck serves to channel souls into the creature itself. As the goat moves through the hills, its lantern casts a sickening yellow glow that attracts the souls of the recently deceased. Lantern goats roam low mountains and foothill damned to patrol the mortal realm in search of those who die alone.\n\nHow the lantern goat behaves in combat depends upon the number of adversaries it faces. Normally the goat preys on lone travelers, attacking them with its stony hooves and horns. If it encounters a group, the lantern goat emits a fear light from its lantern, intending to panic everyone in range and then pick them off individually.","ecology":"","habitat_society":""},{"name":"Large Negative Energy Elemental","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["negative energy (30 ft. radius)"],"ac":21,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +4 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":5,"ref":13,"will":6,"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 slams +15 (1d8+2 plus 1d8 negative energy plus energy drain)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"channel negative energy","details":"3/day, 4d6, DC 16"},{"type":"death throes","details":"30 ft. radius, DC 17, 4d8 negative energy damage"},{"type":"energy drain","details":"1 level, DC 17"},{"type":"negative energy"}],"strength":14,"dexterity":25,"constitution":16,"intelligence":8,"wisdom":11,"charisma":11,"baseatk":8,"cmb":11,"cmd":29,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":20},{"skill":"Intimidate","value":11},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":11},{"skill":"Stealth","value":14}],"languages":["Negative Energy Fluctuation"],"environments":["any (Plane of Negative Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a shimmering and wavering sphere of translucent gray energy with small motes of light winking in and out of existence along its spherical form.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Su","details":"A negative energy elemental that is killed explodes in a flash of swirling negative energy that affects all within the area (the radius for its death throes ability is the same as the radius for its negative energy aura). Living creatures within the area take 1d8 points of negative energy damage per two HD of the elemental. Negative energy based creatures and undead gain hit points equal to the amount of damage the death throes would have otherwise dealt. (The rules for temporary hit points and doubling hit points as detailed under the elemental's negative energy apply here.) A successful Reflex DC (save DC same as the elemental's negative energy save DC) reduces the damage by half."},{"type":"Negative Energy","kind":"Ex","details":"A negative energy elemental infuses a target hit by its slam attack with negative energy. This deals extra damage to a living target (as listed in the statistics block) but heals undead (and other negative energy based creatures) by the same amount. Undead (and other negative energy based creatures) can be healed above their normal hit point total, gaining extra hit points as temporary hit points. These temporary hit points disappear 1 minute later. Creatures healed to twice their normal hit points (that is, a creature whose hit points are effectively doubled) must succeed on a Fortitude save or explode in a burst of negative energy. The save DC is Constitution-based. See the table below for each negative energy elemental's save DC. Negative energy (such as an inflict spell or negative energy channeling) can heal negative energy elementals."},{"type":"Negative Energy Aura","kind":"Su","details":"A negative energy elemental radiates an aura of pure negative energy around it. Within a negative energy elemental's aura, class abilities that use negative energy, such as negative energy channeling or the Command Undead feat, function as if the user were 2 levels higher. Additionally, spells and spell-like abilities that use negative energy are maximized (as if the Maximize Spell metamagic feat had been used on them, but the spells don't require higher-level slots). Spells and spell-like abilities that are already maximized are unaffected by this benefit. This aura doesn't affect the negative energy channeling ability of the negative energy elemental using it, and its effects don't stack with those of other negative energy elementals. Within a negative energy elemental's aura, class abilities that use positive energy, such as positive energy channeling or the Turn Undead feat, function as if the user were 2 levels lower. Spells and spell-like abilities that use positive energy, including cure spells, require the caster to succeed on a Concentration check (DC 15 + the level of the spell). If the check fails, the spell doesn't function but is still lost as a prepared spell or spell slot. If the check succeeds, the spell functions normally."},{"type":"Negative Energy Channeling","kind":"Su","details":"A Large or larger negative energy elemental can channel negative energy as a cleric whose level equals the elemental's Hit Dice. The Will save DC includes a +2 racial bonus."}],"description":"Negative energy elementals are creatures of pure negative energy. They are found primarily on the Negative Energy Plane, but on rare occasions, one slips through a portal or is summoned to the Material Plane. These creatures seem to be able to communicate with others of their kind by changing the intensity of energy in their bodies and altering their shape ever so slightly. They don't speak any known languages. Negative energy elementals hate positive energy elementals and always attack them on sight. Aside from that, negative energy elementals rarely engage in combat. If confronted however and forced into battle, the creature responds by pummeling its foes with its powerful fists dealing negative energy to its foe.","ecology":"","habitat_society":""},{"name":"Large Positive Energy Elemental","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["positive energy (30 ft. radius)"],"ac":21,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +4 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":5,"ref":13,"will":6,"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 slams +15 (1d8+2 plus 1d8 positive energy)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"blinding flash","details":"DC 17"},{"type":"channel positive energy","details":"3/day, 4d6, DC 16"},{"type":"death throes","details":"30 ft. radius, DC 17, 4d8 positive energy damage"},{"type":"positive energy"}],"strength":14,"dexterity":25,"constitution":16,"intelligence":8,"wisdom":11,"charisma":11,"baseatk":8,"cmb":11,"cmd":29,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":20},{"skill":"Intimidate","value":11},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":11},{"skill":"Stealth","value":14}],"languages":["Positive Energy Manipulation"],"environments":["any (Plane of Positive Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a shimmering and wavering sphere of brilliant white energy with small motes of light winking in and out of existence along its spherical form.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blinding Flash","kind":"Su","details":"Once every 1d4 rounds, a positive energy elemental of at least Medium size can release a burst of pure energy in a 10-foot radius. Creatures viewing this burst must succeed on a Fortitude save or be blinded for 1d10 rounds. See the table below for the save DC for each positive energy elemental's blinding flash. The save DC is Constitution-based."},{"type":"Death Throes","kind":"Su","details":"A positive energy elemental that is killed explodes in a flash of blinding positive energy that affects all within the area (the radius for its death throes ability is the same as the radius for its positive energy aura). Undead and negative energy based creatures within the area take 1d8 points of positive energy damage per two HD of the elemental. Positive energy based creatures (including creatures from the Material Plane) gain hit points equal to the amount of damage the death throes would have otherwise dealt. (The rules for temporary hit points and doubling hit points as detailed under the elemental's positive energy apply here.) A successful Reflex DC (save DC same as the elemental's positive energy save DC) reduces the damage by half. All creatures in the area must succeed on a Fortitude save (same DC as the elemental's positive energy save DC) or be blinded for 1d10 rounds. The save DC is Constitution-based."},{"type":"Positive Energy","kind":"Ex","details":"A positive energy elemental infuses a target hit by its slam attack with positive energy. This deals extra damage to an undead or negative energy based target (as listed in the statistics block) but heals positive energy based creatures (including creatures from the Material Plane) by the same amount. Such creatures can be healed above their normal hit point total, gaining extra hit points as temporary hit points. These temporary hit points disappear 1 minute later. Creatures healed to twice their normal hit points (that is, a creature whose hit points are effectively doubled) must succeed on a Fortitude save or explode in a burst of positive energy. The save DC is Constitution-based. See the table below for each positive energy elemental's save DC. Positive energy (such as a cure spell or positive energy channeling) can heal positive energy elementals."},{"type":"Positive Energy Aura","kind":"Su","details":"A positive energy elemental radiates an aura of pure positive energy around it. Within a positive energy elemental's aura, class abilities that use positive energy, such as positive energy channeling or the Turn Undead feat, function as if the user were 2 levels higher. Additionally, spells and spell-like abilities that use positive energy are maximized (as if the Maximize Spell metamagic feat had been used on them, but the spells don't require higher-level slots). Spells and spell-like abilities that are already maximized are unaffected by this benefit. This aura doesn't affect the positive energy channeling ability of the positive energy elemental using it, and its effects don't stack with those of other positive energy elementals. Within a positive energy elemental's aura, class abilities that use negative energy, such as negative energy channeling or the Command Undead feat, function as if the user were 2 levels lower. Spells and spell-like abilities that use negative energy, including inflict spells, require the caster to succeed on a Concentration check (DC 15 + the level of the spell). If the check fails, the spell doesn't function but is still lost as a prepared spell or spell slot. If the check succeeds, the spell functions normally."},{"type":"Positive Energy Channeling","kind":"Su","details":"A Large or larger positive energy elemental can channel positive energy as a cleric whose level equals the elemental's Hit Dice. The Will save DC includes a +2 racial bonus."}],"description":"Positive energy elementals are creatures of pure positive energy. They are found primarily on the Positive Energy Plane, but on rare occasions, one slips through a portal or is summoned to the Material Plane. These creatures seem to be able to communicate with others of their kind by changing the intensity of energy in their bodies and altering their shape ever so slightly. Positive energy elementals hate negative energy elementals and always attack them on sight. Aside from that, positive energy elementals rarely engage in combat. If confronted however and forced into battle, the creature responds by pummeling its foes with its powerful fists dealing positive energy to its foe.","ecology":"","habitat_society":""},{"name":"Larva Helix Moth","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"blindsense","modifier":"60 ft."}],"ac":18,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+9 natural, -1 size","hp":55,"hd":"10d8+10","hdvalue":10,"fort":8,"ref":3,"will":3,"immunities":["vermin traits"],"speed":[{"type":"land","speed":10}],"melee":"bite +9 (1d8+3 plus grab plus 1d6 acid)","space":"10 ft.","reach":"5 ft.","strength":16,"dexterity":10,"constitution":12,"wisdom":11,"charisma":2,"baseatk":7,"cmb":11,"cmd":21,"environments":["any underground"],"organizations":["solitary","nest (2-5)"],"treasure":"none","description_visual":"A monstrously-sized, multi-segmented insect crawls forth on scores of stumpy legs. Its fleshy gray exterior glistens with slime and its great gray mandibles click wildly.","group":"Helix Moth","source":"Tome of Horrors Complete (3pp)","description":"Helix moths are solitary creatures, though on rare occasions a mated pair might be encountered. The lair of an adult helix moth is almost always above ground and usually takes the form of a cave, tunnel, or other such structure.\n\nSuch places are always well-hidden and difficult to reach. When the time comes for a female helix moth to lay her eggs, she hollows out a tunnel in the floor of her lair, forms a large chamber at the end of the tunnel and deposits her eggs in the chamber.\n\nHelix moth larvae lair in a large, 6-foot-diameter ridged tunnels that burrow down into the earth where they eventually open into a large chamber at least 20 square ft. in size. A thick, gray-white slime coats the chamber's floor and walls. Though harmless to living creatures, but generally not pleasant to touch or come in contact with. Occasionally (15% chance) the secretions of the helix moth larva mix with the slime just enough to form a deadly inhalant poison that affects living creatures within the chamber. Those breathing the fumes must make a successful DC 15 Fortitude save or suffer 1d4 points of Constitution damage. A new save must be made every minute. Once a successful save is made, that creature cannot be affected by the fumes again for one day.\n\nTo lay her eggs, the female helix moth uses her acidic secretions and sharpened mandibles to tunnel a hole into the ground and hollow out a large chamber where she lays 2d4 eggs of greenish-gray color.\n\nThe eggs hatch two weeks after fertilization, producing the helix moth larvae, though typically only about 50% of the larva live past the first day.\n\nHelix moths are normally passive creatures except when hunting. During a search for prey, the creature becomes highly aggressive and doesn't hesitate to attack any creature it encounters. A helix moth often journeys up to a mile or more away from its lair in search of prey. Slain prey is carried back to its lair and devoured over a period of several days. The adult helix moth attacks by biting or stinging its prey. Its constant droning affects those that combat it, so the helix moth always tries to stay airborne and within range where it can use this ability while staying out of melee range. Helix moth larvae attack by biting.","ecology":"","habitat_society":""},{"name":"Lilin Devil","cr":6,"xp":2400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+3 Dex, +7 natural","hp":73,"hd":"7d10+35","hdvalue":7,"hp_mods":["regeneration 5 (good, silver)"],"fort":7,"ref":10,"will":10,"dr":"10/silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":17,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"+1 longsword +11 (1d8+4/19-20) or 2 claws +10 (1d6+3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"protection from good"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 3, 2d10 lemures, or 1d4 bearded devils or hellstokers, or 1 hellcat 50%"},{"spell":"unholy aura"}]},{"frequency":"3/day","spells":[{"spell":"animate dead"}]}],"strength":16,"dexterity":16,"constitution":20,"intelligence":15,"wisdom":16,"charisma":26,"baseatk":7,"cmb":10,"cmd":23,"feats":[{"feat":"Alertness"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Persuasive"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Diplomacy","value":19},{"skill":"Fly","value":7},{"skill":"Heal","value":13},{"skill":"Intimidate","value":20},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Survival","value":13}],"languages":["Abyssal","Common","Infernal","telepathy 100 ft."],"environments":["any (Hell)","any (Infernus)"],"organizations":["solitary","pair","harem (6-9)"],"treasure":"standard","description_visual":"A beautiful well-proportioned woman with crimson skin stands before you. Her eyes are dark, almost black as is her hair. A pair of small bat-like wings protrudes from her shoulders. She wields a gleaming longsword in her hand.","group":"Devil","source":"Tome of Horrors Complete (3pp)","description":"Lilins are thought to be the descendants of Lilith, the former Queen of Hell (see her entry elsewhere in this book). Before her coming, lilins were unknown in the Hells. Rumors spoken in hushed whispers say lilins are the offspring of Lilith and an incubus (male demon akin to the succubus). For this, lilins are often viewed with contempt and hatred among devilkind.\n\nAmong the devilish ranks, lilins serve as spies and information gatherers.\n\nThough they possess decent combat skills, they generally don't serve in the hellish armies in any other role. Many an arch-devil, ignoring the foolish rumors that lilins are indeed some demon-devil crossbreed, has employed the services of a lilin on more than one occasion. Even now, many arch-devils keep a small retinue of these devilish mistresses stashed in a rival's palace gathering as much information as they can on each other.\n\nA lilin appears as a crimson-skinned woman about 5-1/2 ft. tall with long dark hair. Her eyes are deep black with flecks of blue. Her wings are black and leathery and her arms end in clawed hands. Lilins dress in light colored flowing gowns and robes and carry their longswords slung at their hips.\n\nA lilin always enters combat with her protection from good in effect and begins by attempting to charm the closest foe. A weak-minded foe that comes within range is subjected to a suggestion. Afterwards she usually attacks with her longsword. If combat goes poorly for a lilin she attempts to flee but not before summoning a host of devils to cover her escape.","ecology":"","habitat_society":"","gear":"+1 longsword"},{"name":"Livestone","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"ooze","init":0,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":9,"ac_touch":9,"ac_flat_footed":9,"ac_mods":"-1 size, +0 natural","hp":76,"hd":"8d8+40","hdvalue":8,"fort":7,"ref":2,"will":-3,"defensive_abilities":["solidify"],"immunities":["petrification","ooze traits"],"speed":[{"type":"land","speed":20}],"melee":"slam +10 (1d8+7)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf","details":"DC 17, 1 acid"}],"strength":20,"dexterity":10,"constitution":20,"wisdom":1,"charisma":1,"baseatk":6,"cmb":12,"cmd":22,"cmd_special":"can't be tripped","skills":[{"skill":"Stealth","value":-4,"special":"+8 in stony areas, +16 while solidified"}],"environments":["any"],"organizations":["solitary","group (2-5)"],"treasure":"none","description_visual":"A large slab of moss-covered rock seems to ooze and move before you.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Engulf","kind":"Ex","details":"A livestone that has engulfed an opponent can instantly solidify its form, dealing 8d6 points of bludgeoning damage per round to the trapped victim (DC 17 Fort half). The save DC is Strength-based. An engulfed creature can be freed by killing the livestone or by casting stone to flesh on the livestone. This deals 1d6 points of damage per caster level to the livestone and automatically ejects an engulfed victim."},{"type":"Solidify","kind":"Ex","details":"A livestone can solidify all or part of itself into a material with the hardness and consistency of solid rock. A solidified part of a livestone has a hardness of 8 and a break DC of 50. A livestone can effect the solidification as a free action. An opponent attacking a livestone must succeed on a DC 19 Reflex save each time his attack hits. If the save is failed, the livestone actually solidifies the portion of its body at the instant it was hit, thus applying its hardness rating of 8 to any damage it takes. A livestone cannot attack if its entire form is solidified. The save DC is Strength-based."}],"description":"Livestone is a strange species of ooze that can solidify itself into a consistency that very closely resembles that of stone. In its solidified form, a livestone is indistinguishable from a normal boulder or slab of rock. No one is quite sure from where livestones originated, but ancient legends say that the dwarves accidentally unleashed these horrors on the surface world by digging into their subterranean lairs. Eventually, some livestones found their way to the surface. Livestones are incredibly longlived, solidifying and entering a form of hibernation and remaining that way indefinitely until a food source wanders too near. Livestones have a simple chameleon-like ability to mimic local stone by ingesting a small sample and adjusting its own color and texture to match. A hibernating livestone can become covered in moss and lichens to further the deception.\n\nLivestones generally attack from ambush, waiting for a potential meal to pass before flowing into their ooze form and rushing up to engulf the prey. If the surprise attack fails, a livestone resorts to hammering with a pseudopod. When attacking in this manner, a livestone will solidify the tip of the pseudopod and strike with a hammer-like blow. A livestone's usual tactic is to solidify the half of its body facing the prey and then send hard-tipped pseudopods out from behind this shield (see solidify above).","ecology":"","habitat_society":""},{"name":"Magnesium Golem","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["aura of sickness (10 ft., DC 16, sickened 1d4 minutes)"],"ac":18,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +7 natural","hp":64,"hd":"8d10+20","hdvalue":8,"fort":2,"ref":3,"will":2,"dr":"10/adamantine","immunities":["construct traits","magic"],"weaknesses":["rust vulnerability"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +10 (2d6+2 plus 1d4 Dexterity damage)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":13,"wisdom":11,"charisma":1,"baseatk":8,"cmb":10,"cmd":21,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"Silvery-white powder shakes loose from this construct as it stomps across the floor. Its face is a featureless plane except for two gouges where there should be eyes.","group":"Golem","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Sickness","kind":"Su","details":"As a free action, a magnesium golem can generate an aura in a 10-foot radius spread that sickens all living creatures entering the area for 1d4 minutes if that creature fails a DC 16 Fortitude save. A creature that successfully saves cannot be affected again by the same magnesium golem's aura of sickness for 24 hours. A delay poison or neutralize poison spell removes the effect from a sickened creature. This is a poison effect. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Dexterity Damage","kind":"Su","details":"A magnesium golem's slam attack deals 1d4 points of Dexterity damage to a living foe if it fails a DC 14 Fortitude save. The save DC is Constitution-based."},{"type":"Immunity to Magic","kind":"Ex","details":"A magnesium golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature as noted below. A magic attack that deals water damage or creates water slows a magnesium golem (as the slow spell) for 3 rounds, with no saving throw. A magical effect that deals fire damage breaks any slow effect and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A magnesium golem gets no saving throw against fire effects."},{"type":"Rust Vulnerability","kind":"Ex","details":"A magnesium golem is affected normally by rust attacks, such as that of a rust monster or a rusting grasp spell."}],"description":"Magnesium golems are silvery-white humanoids created by arcane spellcasters. As with other golems, they are incapable of thinking on their own, and are thus under control of the one that created them. They are created as guardians and keepers and can be given specific orders to guard a specific locale, item, or object or to attack a specific creature or type of creature. The magnesium golem is a silvery-white humanoid formed of magnesium. The average magnesium golem stands about 6-7 ft. tall and weighs 600 pounds. The magnesium golem's features are smooth and perfect, though it has no discernable ears, nose, or mouth. Its eyes appear to be nothing more than indentations in its body. Magnesium golems wear no clothing and never carry weapons, and it cannot speak or make any vocal noise. Unlike many other golems, the magnesium golem can move at the same speed as a human of its size. Construction A magnesium golem's body is sculpted from 1,000 pounds of pure magnesium. The magnesium is mixed with rare chemicals totaling 4,000 gp. Assembling the body requires a successful DC 14 Craft (armor or weapons) check. MAGNESI GOLEM CL 9th; Price 27,000 gp Requirements Craft Construct, geas/quest, hold monster, limited wish, polymorph any object, stinking cloud, creator must be caster level 9th; Skill Craft (armor) or Craft (weapons) DC 14; Cost 15,500 gp Anodized (Improved) Magnesium Golem The golem is anodized during the creation process by submerging it in a solution of acid. During this time, the creator must cast lightning bolt or some other electricity-based effect into the solution. This deals no damage to the golem. After four hours, the magnesium golem is removed from the solution. An anodized magnesium golem is identical to a normal magnesium golem detailed above but it doesn't have the rust vulnerability trait of the normal magnesium golem. This increases the golem's price by 2,000 gp.","ecology":"","habitat_society":""},{"name":"Malkeen","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +4 natural, -1 size","hp":76,"hd":"8d10+32","hdvalue":8,"fort":10,"ref":8,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":40}],"melee":"2 claws +13 (1d6+5), bite +12 (1d8+5)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"mind blast"},{"type":"pounce"},{"type":"rake","details":"2 claws +13, 1d6+5"}],"strength":21,"dexterity":15,"constitution":18,"intelligence":6,"wisdom":14,"charisma":12,"baseatk":8,"cmb":14,"cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Perception","value":10},{"skill":"Stealth","value":7,"special":"+11 in marshes"},{"skill":"Swim","value":10}],"languages":["Common","telepathy 100 ft."],"environments":["temperate marshes","warm marshes"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This large cat resembles a brown-furred leopard.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Mind Blast","kind":"Su","details":"As a standard action, a malkeen can deliver a massive blast of mental energy at a single target within 50 ft. The target must succeed on a DC 15 Will save or take 6d6 points of damage. A malkeen can use this ability once every 1d6 rounds. The save DC is Charisma-based."}],"description":"Malkeens are intelligent, ferocious swamp cats that closely resemble dark furred leopards. These creatures are extremely territorial with the average malkeen's territory covering 10 square miles or more. Creatures entering its territory are stalked and watched from afar before the malkeen moves in to attack. Malkeens are generally passive creatures and only attack if threatened or hungry. They are carnivores and dine on creatures such as alligators, marsh reptiles, marsh birds, and wild game.\n\nMalkeens reach lengths of 12 ft. or more and weigh up to 5,500 pounds. Malkeens can live for up to 50 years.\n\nMalkeens are ambush hunters and sneak up on their prey before lunging to attack. These creatures almost always open combat with their mind blast attack, attempting to kill or disable their opponent as quickly as possible. After that, opponents left standing are assaulted by claws and bites.","ecology":"","habitat_society":""},{"name":"Medium Lightning Quasi-elemental","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","electricity","elemental","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["globe (5 ft., Ref DC 19, 1d6 electricity)"],"ac":20,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+6 Dex, +1 dodge, +3 natural","hp":75,"hd":"10d10+20","hdvalue":10,"fort":5,"ref":13,"will":7,"dr":"5/-","immunities":["electricity","elemental traits"],"resists":[{"type":"acid","value":10},{"type":"fire","value":10}],"weaknesses":["vulnerability to water"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"2 slams +16 (1d8 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"electricity"}],"strength":12,"dexterity":22,"constitution":14,"intelligence":4,"wisdom":11,"charisma":11,"baseatk":10,"cmb":11,"cmd":28,"feats":[{"feat":"Ability Focus (globe)"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":27},{"skill":"Perception","value":13},{"skill":"Stealth","value":19}],"languages":["Auran"],"environments":["any (Quasi-Plane of Lightning)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a bluish globe of electrical energy. Lightning plays off and around its body.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Electricity","kind":"Ex","details":"A lightning quasi-elemental is composed entirely of electricity and deals electricity damage each time it hits. A creature striking the lightning quasi-elemental unarmed, or a creature striking the lightning quasi-elemental with a weapon take this same electricity damage each time one of their attacks hits. Metallic creatures or creatures using metal weapons take an extra 1d6 points of electricity damage each time one of their attacks hits."},{"type":"Globe","kind":"Ex","details":"As a standard action, a lightning quasi-elemental can discharge one globe of electricity per HD it possesses once per round. Globes hover by the quasi-elemental and move with the creature. An opponent that moves within 5 ft. of a lightning quasi-elemental discharges a globe and takes the electricity damage shown on the table below. An affected creature can make a Reflex save to reduce the damage by half. The save DC is Constitution-based. Once a globe discharges, it is destroyed and a lightning quasi-elemental cannot recreate it for 4 hours."},{"type":"Vulnerability to Water","kind":"Ex","details":"A lightning quasi-elemental takes 1d8 points of damage per gallon of water it contacts. Pouring water onto a lightning quasi-elemental requires a successful ranged touch attack. Water from other sources, such as spells or effects that create water but don't specify an amount in gallons, deal 1d4 points of damage per caster level to a lightning quasi-elemental within its area of effect. Damage from water-based attacks, like the slam attack of a water elemental, is increased by 50% against a lightning quasi-elemental."}],"description":"Lightning quasi-elementals are native to the Plane of Air, the Positive Energy Plane, and a rumored elemental plane situated in between (the Quasi-Plane of Lightning). They are sometimes summoned to the Material Plane by wizards or clerics, but more often than not slip through a rift between the Material Plane and elemental plane during a lightning storm. A lightning quasi-elemental can release small globes of electricity that hover around its body. An opponent that moves within 5 ft. of a globe causes it to arc and discharge.","ecology":"","habitat_society":"","credit":"The Lightning Quasi-elemental originally appeared in the First Edition module EX2 The Land Beyond the Magic Mirror (© TSR/Wizards of the Coast, 1983) and later in the First Edition Monster Manual II (© TSR/ Wizards of the Coast, 1983) and is used by permission."},{"name":"Memory Child","cr":6,"xp":2400,"alignment":"N","size":"Small","type":"outsider","subtypes":["extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":68,"hd":"8d10+16 (+8)","hdvalue":8,"fort":8,"ref":6,"will":10,"dr":"10/silver","speed":[{"type":"land","speed":30}],"melee":"touch +9 (1d4 plus thought consumption)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mind flood"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect thoughts"}]}],"strength":10,"dexterity":14,"constitution":14,"intelligence":12,"wisdom":15,"charisma":11,"baseatk":8,"cmb":7,"cmd":19,"feats":[{"feat":"Alertness"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":4},{"skill":"Disguise","value":5},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (history)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":15},{"skill":"Perform (oratory)","value":11},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":15},{"skill":"Survival","value":3}],"languages":["Celestial","Common","telepathy 100 ft."],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"A small innocent child, seemingly confused or lost, stands in front of you.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Mind Flood","kind":"Su","details":"As a standard action and by touching an opponent, a memory child floods the opponent's mind with every single thought the child has ever collected from those that have come into contact with it. This effect overloads the opponent's brain dazing it for 1d6+2 rounds and confusing it for 1 hour (treat as a confusion spell, caster level equals the memory child's Hit Dice). A successful DC 16 Will save negates the stunning effect and reduces the confusion effect to 1 minute. The save DC is Constitution-based. This ability is always active but can be suppressed or restarted by the memory child as a free action."},{"type":"Thought Consumption","kind":"Su","details":"A memory child can drain an opponent's thoughts and memories by touch. (The opponent retains its memories; the memory child just copies them). By making a successful melee touch attack, a memory child deals 1d4 points of Intelligence damage to its opponent. A memory child must consume at least 4 points of Intelligence each day or it suffers the effects of starvation."}],"description":"A memory child is an extraplanar being from an unknown plane of existence whose sole purpose is the harvesting and collecting of memories from all of those it encounters. Such memories function as food for the memory child (though it retains all memories collected; that is, they are not actually devoured and don't disappear). Memory children take delight in traveling to the Material Plane and so are most often encountered there, especially in places where intelligent creatures reside such as cities and towns.\n\nA memory child waits until the perfect moment to use its abilities. It rarely if ever engages in melee, preferring to flee rather than engage a foe in combat. If possible, it uses its special abilities to make such combat unnecessary.\n\nTo the observer, a memory child looks exactly like an ordinary child (male or female) about 7 or 8 years old with delicate features, pale skin, and innocent eyes of blue (all memory children have blue eyes).\n\nRegardless of its actual age, a memory child never seems to grow up or grow old.","ecology":"","habitat_society":""},{"name":"Metallic Ooze","cr":6,"xp":2400,"alignment":"N","size":"Large","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size, +0 natural","hp":87,"hd":"7d8+56","hdvalue":7,"fort":10,"ref":-3,"will":-3,"immunities":["ooze traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":10}],"melee":"slam +7 (1d8+4 plus 1d6 acid plus poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"irritating fumes"}],"strength":17,"dexterity":1,"constitution":26,"wisdom":1,"charisma":1,"baseatk":5,"cmb":9,"cmd":14,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":11}],"environments":["any underground"],"organizations":["solitary"],"treasure":"double standard","description_visual":"A large pile of seemingly unguarded coins lies before you.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Irritating Fumes","kind":"Ex","details":"If a metallic ooze is subjected to a heat or fire effect, it emanates a cloud of semi-transparent vapor that irritates the eyes and respiratory system of living creatures within a 10-foot radius. Affected creatures must succeed on a DC 21 Fortitude save or take 2d6 points of acid damage initially and suffer a -2 circumstance penalty on attack and weapon damage rolls for 3 rounds. The cloud disperses in 1d4 rounds and can be affected by wind. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Slam-injury; save Fort DC 21; frequency 1/round for 6 rounds; effect 1d2 Dexterity damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"A metallic ooze appears as a 9-foot blob of protoplasm of varying hue and color, and come in a variety of sizes and colors: gold, silver, platinum, copper, brass, or bronze. Regardless of the color or size, metallic oozes resemble large piles of coins. The oozes use their appearance to lure wouldbe treasure hunters to their doom. Because of this, they are sometimes referred to as hoard oozes. Its form is coarse and rough giving it the appearance of piles of coins. A metallic ooze can flatten its body in order to squeeze through spaces and cracks where it normally could not go. A metallic ooze can be found virtually anywhere, though it tends to inhabit dungeons, ruined temples, castles, and other buildings where treasure seekers seem to enjoy perfecting their craft. From a distance of 30 ft. or more, a metallic ooze resembles a pile of loose coins (of whatever type its coloration most closely resembles). A creature can attempt a DC 20 Perception check to notice the ooze for what it is. This monster doesn't collect treasure, but the remnants of living creatures that meet their demise at the hands of this creature are often found scattered about its lair. A metallic ooze lies still until it detects a potential meal within range. It then forms a pseudopod and pummels the opponent. Creatures killed by a metallic ooze are devoured. While a metallic ooze can cling to walls and ceilings (and often does drop on unsuspecting prey), it prefers to wander dungeon corridors and such on the ground, often waiting in one spot until living prey wanders too close.","ecology":"","habitat_society":""},{"name":"Midnight Peddler","cr":6,"xp":2400,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+1 Dex, +1 dodge, +5 natural","hp":52,"hd":"7d10+14","hdvalue":7,"fort":6,"ref":6,"will":4,"speed":[{"type":"land","speed":20}],"melee":"touch +7 (death chill)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death chill"}],"strength":11,"dexterity":13,"constitution":15,"intelligence":16,"wisdom":18,"charisma":15,"baseatk":7,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":24,"cmd_special":"+8 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Craft (wood)","value":12},{"skill":"Diplomacy","value":8},{"skill":"Knowledge (history)","value":9},{"skill":"Knowledge (local)","value":9},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":16},{"skill":"Profession (peddler)","value":10},{"skill":"Sense Motive","value":16},{"skill":"Survival","value":10}],"languages":["Common","Celestial","Abyssal","Terran"],"sq":[{"type":"divination"},{"type":"plane shift"}],"environments":["any land"],"organizations":["solitary"],"treasure":"none (see text)","description_visual":"This creature appears as a normal human, cloaked in a long gray hooded robe. A long protruding, sharp jaw can be seen under the hood.  He moves with a shuffling gait, pushing a wooden cart that squeaks as it rolls along.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Chill","kind":"Su","details":"The touch of the midnight peddler deals 1d4 negative levels to a living creature. The DC is 15 for the Fortitude save to remove a negative level. The save DC is Constitution-based. The midnight peddler gains 5 temporary hit points for each negative level bestowed."},{"type":"Divination","kind":"Su","details":"The peddler provides advice and answers correctly any one question asked of him by any creature who buys something from his cart. This ability functions similar to a divination spell (caster level 12th)."},{"type":"Plane Shift","kind":"Su","details":"The midnight peddler can plane shift (as the spell) to any inner or outer plane as a move action. His cart (and any non-living matter contained therein) shifts with him. This ability otherwise functions as the spell of the same name."}],"description":"The midnight peddler wanders city streets and is normally only encountered on fog-covered nights. He is first detected by the audible squeaking of the cart he pushes, the sound growing louder as he draws closer. The sound can be heard at a range of 300 ft. with a successful DC 12 Perception check. The midnight peddler moves with a slow gait as he pushes his wooden cart. The contents of his cart vary each time he visits the Material Plane, but at any given time, he has available any equipment with a value of 50 gp or less.\n\nThe midnight peddler shuns combat. If forced into battle, he uses his death chill ability at first opportunity and then plane shifts away.","ecology":"","habitat_society":""},{"name":"Mihstu","cr":6,"xp":2400,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":23,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +1 dodge, +6 natural","hp":60,"hd":"8d10+16","hdvalue":8,"fort":8,"ref":12,"will":4,"defensive_abilities":["resistance to missile attacks"],"dr":"10/ magic","immunities":["electricity","elemental traits"],"sr":13,"weaknesses":["susceptible to cold"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":20,"maneuverability":"good"}],"melee":"4 tentacles +14(1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constitution damage"},{"type":"engulf"}],"strength":12,"dexterity":22,"constitution":14,"intelligence":14,"wisdom":14,"charisma":13,"baseatk":8,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":26,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Escape Artist","value":14},{"skill":"Fly","value":21},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":17},{"skill":"Survival","value":10}],"environments":["any (Plane of Air)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature appears as a semi-solid cloud of vapor and mist.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Constitution Damage","kind":"Su","details":"A mihstu deals 1d2 points of Constitution damage to an engulfed opponent each round the hold is maintained."},{"type":"Engulf","kind":"Ex","details":"A mihstu can try to wrap a Medium or smaller creature in its body as a standard action. The mihstu attempts a grapple that doesn't provoke an attack of opportunity. If it wins the grapple check, it establishes a hold and can slash (with a tentacle) the engulfed victim with a +4 bonus on its attack roll. It can still use its tentacles to strike at other targets. Attacks that hit an engulfing mihstu deal half their damage to the monster and half to the trapped victim."},{"type":"Resistance to Missile Attacks","kind":"Ex","details":"Ranged attacks (including magic missile) used against a mihstu have a 50% miss chance."},{"type":"Susceptible to Cold","kind":"Ex","details":"Cold-based attacks and effects deal no damage to a mihstu, but stun it. If the cold-based effect allows a saving throw and the mihstu succeeds on its save, it ignores the stun effect. If it fails its save, or if the effect doesn't allow a save, the mihstu is stunned for 1d4+2 rounds."}],"description":"Mihstus are semi-solid creatures from the Plane of Air. They are found in cool, damp, dark areas such as ruins, dungeons, and underground caves and caverns. The mihstu can shape its body at will and almost always appears on the Material Plane as a cloud of swirling vapor. It can seep through small cracks and openings. When threatened, a mihstu forms four tentacles from its body. Each tentacle ends in a razor-sharp, barb-like talon. It slashes at its opponents using these tentacles. The mihstu can also engulf an opponent in its misty form. A mihstu's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.","ecology":"","habitat_society":"","credit":"The Mihstu originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."}];
